    by=dno
).CALCULATE(
    department_name=department.dname,
    student_count=COUNT(minor_ins)
).TOP_K(1, by=student_count.DESC()).CALCULATE(
    department_name=department_name
)

most_reviewed_movie = Rating.PARTITION(
    name="movie_groups", by=mID
).CALCULATE(
    mID=mID,
    review_count=COUNT(Rating)
).movie.CALCULATE(
    movie_title=title,
    review_count=review_count
).ORDER_BY(review_count.DESC(), movie_title.ASC()).TOP_K(1, by=review_count.DESC())

# Find the most common party form by counting how many parties use each form
most_common_form = party_form.CALCULATE(
    form_name=form.form_name,
    form_id=form_id
).PARTITION(name="form_groups", by=form_id).CALCULATE(
    form_name=form_name,
    usage_count=COUNT(party_form)
).TOP_K(1, by=usage_count.DESC()).CALCULATE(
    form_name=form_name
)

stadium_with_most_events = stadiums.WHERE(
    HAS(events)
).CALCULATE(
    stadium_name=name,
    event_count=COUNT(events)
).TOP_K(1, by=event_count.DESC()).CALCULATE(
    stadium_name=stadium_name
)

# Find the ship that caused the most total casualties (death records)
ship_with_most_casualties = deaths.PARTITION(
    name="ship_groups", by=caused_by_ship_id
).CALCULATE(
    ship_id=caused_by_ship_id,
    total_casualties=COUNT(deaths)
).TOP_K(1, by=total_casualties.DESC()).CALCULATE(
    ship_id=ship_id,
    ship_name=ship.name
)

# Calculate total balance (checking + savings) for customers with both account types, ordered by total
customer_total_balances = checkings.WHERE(
    HAS(saving) == 1
).CALCULATE(
    total_balance=balance + saving.balance
).ORDER_BY(total_balance.ASC())

# Find the course_id for Mobile Computing
mobile_computing_course = course.WHERE(title == "Mobile Computing").CALCULATE(
    mobile_course_id = course_id
)

# Find prerequisite course IDs for Mobile Computing
mobile_computing_prereq_ids = prereq.WHERE(
    ISIN(course_id, mobile_computing_course.mobile_course_id)
).CALCULATE(
    prereq_course_id = prereq_id
)

# Get the titles of the prerequisite courses
result = course.WHERE(
    ISIN(course_id, mobile_computing_prereq_ids.prereq_course_id)
).CALCULATE(
    prerequisite_title = title
)

# Find courses that have "Differential Geometry" as a prerequisite
courses_with_diff_geom_prereq = prereqs.CALCULATE(
    prereq_course_title = courses.WHERE(course_id == prereq_id).title.SINGULAR(),
    main_course_title = courses.WHERE(course_id == prereqs.course_id).title.SINGULAR()
).WHERE(
    prereq_course_title == "Differential Geometry"
).CALCULATE(
    course_title = main_course_title
)

total_balance_not_brown = saving.WHERE(account.name != "Brown").CALCULATE(
    total_balance=SUM(balance)
).total_balance

# Filter entrepreneurs by height > 1.85 and calculate total money requested
total_money_tall_entrepreneurs = entrepreneurs.WHERE(
    person.height > 1.85
).CALCULATE(
    total_money_requested = SUM(money_requested)
)

# Calculate average max speed across all storms and filter for above-average storms
result = storm_record.CALCULATE(
    avg_max_speed = AVG(storms.CALCULATE(max_speed_num = max_speed + 0.0).max_speed_num)
).storms.WHERE(
    (max_speed + 0.0) > avg_max_speed
).CALCULATE(
    total_deaths = SUM(CALCULATE(deaths_num = number_deaths + 0.0).deaths_num),
    total_damage_millions_usd = SUM(damage_millions_usd)
)

# Find colleges that do not have any goalie players and sum their enrollment
colleges_without_goalies = colleges.WHERE(
    HASNOT(tryouts.WHERE(pPos == "goalie")) == 1
).CALCULATE(
    total_enrollment = SUM(enr)
)

# Count people who have no friends living in Austin
result = people.WHERE(
    HASNOT(personfriends.WHERE(person.city == "Austin")) == 1
).CALCULATE(
    total_count = COUNT(people.name)
)

# Calculate the total population for districts with city area larger than average
result = store_product.CALCULATE(
    avg_city_area=AVG(districts.city_area)
).districts.WHERE(
    city_area > avg_city_area
).CALCULATE(
    total_population=SUM(city_population)
).total_population

# Find the total enrollment of colleges without any goalies
colleges_without_goalies = colleges.WHERE(
    ~HAS(tryouts.WHERE(ppos == "goalie"))
).CALCULATE(
    total_enrollment = SUM(enr)
)

# Filter manufacturers with headquarters in Tokyo or Taiwan and calculate total revenue
total_revenue_result = manufacturer.WHERE(
    (headquarter == "Tokyo") | (headquarter == "Taiwan")
).CALCULATE(
    total_revenue=SUM(revenue)
)

# Filter apartments with more than one bathroom and find the most common apartment type code
most_common_apt_type = Apartments.WHERE(
    bathroom_count > 1
).PARTITION(
    name="apt_types", 
    by=apt_type_code
).CALCULATE(
    apt_type_code=apt_type_code,
    count_apartments=COUNT(Apartments)
).TOP_K(1, by=(count_apartments.DESC(), apt_type_code.DESC()))

# Find catalog contents with length below 3 or above 5
catalog_entries_filtered = catalog_content.WHERE(
    (TONUMBER(length) < 3) | (TONUMBER(length) > 5)
).CALCULATE(
    catalog_entry_name=catalog_entry_name
)

# Find customers who have used both "Close a policy" and "Upgrade a policy" services
customers_with_both_services = customer.WHERE(
    HAS(customers_policy.first_notification_of_losses.WHERE(
        service.service_name == "Close a policy"
    )) == 1
).WHERE(
    HAS(customers_policy.first_notification_of_losses.WHERE(
        service.service_name == "Upgrade a policy"
    )) == 1
).CALCULATE(customer_name=customer_name)

club_with_most_female_members = clubs.WHERE(
    HAS(member_of_clubs)
).CALCULATE(
    club_name=clubname,
    female_member_count=COUNT(member_of_clubs.student.WHERE(sex == "F"))
).TOP_K(1, by=(female_member_count.DESC(), club_name.ASC())).CALCULATE(
    club_name=club_name
)

makers_with_many_models = car_maker.WHERE(
    COUNT(model_lists) > 3
).CALCULATE(
    maker_id=id,
    full_name=fullname
)

# Find Solveig's most performed vocal type
result = bands.WHERE(firstname == "Solveig").vocal.PARTITION(
    name="vocal_types", by=type
).CALCULATE(
    performance_count=COUNT(vocal)
).TOP_K(1, by=performance_count.DESC()).CALCULATE(type)

# Find people who have friends from New York City
people_with_nyc_friends = personfriends.WHERE(
    people.WHERE(name == friend).city == "new york city"
).CALCULATE(
    name=name
).PARTITION(name="unique_people", by=name).CALCULATE(
    name=name
)

# Calculate average age and find people who have friends younger than average
result = network_2.CALCULATE(
    avg_age = AVG(people.age)
).people.WHERE(
    HAS(personfriends.WHERE(
        people.WHERE(name == friend).age < avg_age
    ))
).CALCULATE(
    person_name = name
)

advisor_results = voting_records.WHERE(
    (election_cycle == "Spring") & 
    (treasurer_vote != None)
).CALCULATE(
    student_id_voted_for = treasurer_vote
).students.WHERE(
    stuid == student_id_voted_for
).CALCULATE(
    advisor_id = advisor
)

# Find employees who report to a manager named Payam
employees_reporting_to_payam = employee.WHERE(
    manager_id.IN(
        employee.WHERE(first_name == "Payam").employee_id
    )
).CALCULATE(
    employee_id = employee_id,
    salary = salary
)

# Find employees working in departments located in London
london_employees = employee.WHERE(
    HAS(department) == 1
).department.WHERE(
    location_id.ISIN(location.WHERE(city == "London").location_id)
).employee.CALCULATE(
    full_name=JOIN_STRINGS(' ', first_name, last_name),
    salary=salary
)

# Count crimes classified as "Drugs"
drug_crimes_count = GreaterManchesterCrime.WHERE(
    Type == "Drugs"
).CALCULATE(
    total_drug_crimes=COUNT(CrimeID)
)

# Get total degrees granted between 1998-2002 across all campuses
total_degrees_1998_2002 = degree.WHERE(
    (Year >= 1998) & (Year <= 2002)
).CALCULATE(
    total_degrees=SUM(Degrees)
)

# Find the most common crime type by grouping and counting
crime_type_counts = GreaterManchesterCrime.CALCULATE(
    crime_type=Type
).PARTITION(
    name="crime_groups", 
    by=crime_type
).CALCULATE(
    crime_type=crime_type,
    crime_count=COUNT(GreaterManchesterCrime)
).TOP_K(1, by=crime_count.DESC())

# Group crimes by complete timestamp and count occurrences
crime_by_timestamp = greatermanchestercrimes.PARTITION(
    name="timestamps", by=crimets
).CALCULATE(
    crime_count=COUNT(greatermanchestercrimes)
)

# Find the timestamp with the most crimes and return only the timestamp
most_frequent_time = crime_by_timestamp.TOP_K(1, by=crime_count.DESC()).CALCULATE(
    timestamp=crimets
)
